function openLedgerPrintOptions(){if(!currentLedgerConsumer){showBillMessage('Select an account before printing its ledger.');return}let dialog=$('#ledger-print-options');if(!dialog){dialog=document.createElement('dialog');dialog.id='ledger-print-options';dialog.className='bill-dialog ledger-print-options';dialog.innerHTML='<form method="dialog"><header><div><p class="eyebrow">Net Metering</p><h2>Print Billing Ledger</h2></div><button type="button" class="secondary" data-close>Cancel</button></header><div class="ledger-print-options-fields"><label>Period<select name="period"><option value="all">Whole history</option><option value="year">One year</option></select></label><label>Year<select name="year"></select></label><label class="ledger-print-graph"><input name="graph" type="checkbox" checked> Include consumption graph</label></div><footer><button type="button" class="secondary" data-close>Cancel</button><button type="submit">Continue to print</button></footer></form>';document.body.append(dialog);dialog.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelector('[name=period]').onchange=()=>{dialog.querySelector('[name=year]').disabled=dialog.querySelector('[name=period]').value==='all'};dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);dialog.close();await printConsumerLedger({period:form.get('period'),year:form.get('year'),graph:form.has('graph')})}}
  const years=[...new Set(currentLedgerHistory.map(row=>`20${String(row.billMonth||'').slice(2)}`).filter(value=>/^20\d{2}$/.test(value)))].sort().reverse(),yearSelect=dialog.querySelector('[name=year]');yearSelect.innerHTML=years.map(year=>`<option value="${year}">${year}</option>`).join('');dialog.querySelector('[name=period]').value='all';yearSelect.disabled=true;dialog.showModal()}
