function openConsumerManager(){const select=$('#consumer-manager-database');select.innerHTML=catalog.databases.map(item=>`<option value="${escapeHtml(item.database)}">${escapeHtml(item.label)}</option>`).join('');if($('#database').value!=='all')select.value=$('#database').value;$('#consumer-manager-message').textContent='';$('#consumer-manager-dialog').showModal();loadConsumerProfiles(1)}
