function runNetMeteringMenuAction(){const action=location.hash;if(action==='#teller')openTellerWorkflow();else if(action==='#reading-schedule')openReadingSchedule();else if(action==='#entry')$('#create-bill')?.click();else if(action==='#new-consumer')openConsumerManager();else if(action==='#ledger-print')openAccountWorkflow('ledger');else if(action==='#profile')openAccountWorkflow('profile');else if(action==='#rates')$('#rates-dialog').showModal();else if(action==='#payment-posting')document.querySelector('#bill-list').scrollIntoView({behavior:'smooth'})}
window.addEventListener('hashchange',runNetMeteringMenuAction);runNetMeteringMenuAction();
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="/netmetering#"]');if(link){const action=new URL(link.href).hash;if(action==='#teller'){event.preventDefault();openTellerWorkflow();return}if(action==='#rates'){event.preventDefault();$('#rates-dialog').showModal();return}if(action==='#reading-schedule'){event.preventDefault();openReadingSchedule();return}if(action==='#new-consumer'){event.preventDefault();openConsumerManager();return}if(action==='#payment-posting'){event.preventDefault();$('#bill-list').scrollIntoView({behavior:'smooth'});return}if(['#entry','#profile','#ledger-print'].includes(action)){event.preventDefault();if(action==='#entry')$('#create-bill').click();else openAccountWorkflow(action==='#profile'?'profile':'ledger');return}const monthLink=link.dataset.month;if(monthLink!==undefined){event.preventDefault();$('#bill-month').value=monthLink;load();$('#bill-list').scrollIntoView({behavior:'smooth'});link.closest('details').open=false}}});
