function renderScheduleRouteFilters(){const area=$('#schedule-area'),book=$('#schedule-book'),oldArea=area.value,oldBook=book.value,areas=[...new Set(scheduleRoutes.map(row=>String(row.area)))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));area.innerHTML='<option value="ALL">ALL</option>'+areas.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');area.value=areas.includes(oldArea)?oldArea:'ALL';const books=[...new Set(scheduleRoutes.filter(row=>area.value==='ALL'||String(row.area)===area.value).map(row=>String(row.book)))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));book.innerHTML='<option value="ALL">ALL</option>'+books.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');book.value=books.includes(oldBook)?oldBook:'ALL'}
async function openReadingSchedule(){const select=$('#schedule-database');select.innerHTML=catalog.databases.map(item=>`<option value="${escapeHtml(item.database)}">${escapeHtml(item.label)}</option>`).join('');if($('#database').value!=='all')select.value=$('#database').value;selectedSchedule=null;$('#reading-schedule-dialog').showModal();await loadSchedule(1)}
function openScheduleEditor(row=null){const form=$('#schedule-entry-form');form.reset();$('#schedule-entry-database').value=$('#schedule-database').value;$('#schedule-id').value=row?.id||'';$('#schedule-entry-title').textContent=row?'Edit Reading Schedule':'Schedule Reading - Adding';$('#schedule-delete').hidden=!row;$('#schedule-entry-message').hidden=true;const grids=$('#schedule-entry-grid');grids.innerHTML=Array.from({length:9},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');const area=$('#schedule-entry-area'),areas=[...new Set(scheduleRoutes.map(item=>String(item.area)))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));area.innerHTML=areas.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');const selectedArea=row?.area||areas[0]||'';area.value=selectedArea;function setBooks(preferred=''){const options=scheduleRoutes.filter(item=>String(item.area)===area.value).map(item=>String(item.book));const unique=[...new Set(options)].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));$('#schedule-entry-book').innerHTML=unique.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');if(unique.includes(preferred))$('#schedule-entry-book').value=preferred}setBooks(row?.book||'');area.onchange=()=>setBooks();$('#schedule-entry-month').value=row?.billMonth||($('#schedule-month').value==='ALL'?`${String(new Date().getMonth()+1).padStart(2,'0')}${String(new Date().getFullYear()).slice(-2)}`:$('#schedule-month').value);grids.value=String(row?.grid||1);$('#schedule-entry-previous').value=row?.previousDate||'';$('#schedule-entry-present').value=row?.presentDate||'';$('#schedule-entry-due').value=row?.dueDate||'';$('#schedule-entry-disconnection').value=row?.disconnectionDate||'';$('#schedule-entry-dialog').showModal()}
