$('#schedule-close').onclick=()=>$('#reading-schedule-dialog').close();$('#schedule-close-bottom').onclick=()=>$('#reading-schedule-dialog').close();$('#schedule-add').onclick=()=>openScheduleEditor();$('#schedule-load').onclick=()=>loadSchedule(1);$('#schedule-database').onchange=()=>loadSchedule(1);$('#schedule-month').onchange=()=>{renderScheduleRouteFilters()};$('#schedule-area').onchange=()=>{renderScheduleRouteFilters()};$('#schedule-book').onchange=()=>loadSchedule(1);$('#schedule-first').onclick=()=>loadSchedule(1);$('#schedule-prev').onclick=()=>loadSchedule(Math.max(1,schedulePage-1));$('#schedule-next').onclick=()=>loadSchedule(Math.min(schedulePages,schedulePage+1));$('#schedule-last').onclick=()=>loadSchedule(schedulePages);$('#schedule-print').onclick=()=>window.print();$('#schedule-entry-cancel').onclick=closeScheduleEditor;$('#schedule-entry-cancel-bottom').onclick=closeScheduleEditor;
function updateScheduleDates(){const value=$('#schedule-entry-present').value;if(!value)return;const base=new Date(`${value}T00:00:00Z`);if(Number.isNaN(base.getTime()))return;const format=days=>{const date=new Date(base);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)};$('#schedule-entry-due').value=format(9);$('#schedule-entry-disconnection').value=format(11)}
$('#schedule-entry-present').addEventListener('input',updateScheduleDates);$('#schedule-entry-present').addEventListener('change',updateScheduleDates);
$('#schedule-entry-form').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));try{const response=await fetch('/api/netmetering-schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error);selectedSchedule={id:result.id};closeScheduleEditor();await loadSchedule(schedulePage)}catch(error){const message=$('#schedule-entry-message');message.textContent=error.message;message.hidden=false}};
